import { beforeEach, describe, expect, it } from 'vitest';

import type Redis from 'ioredis';

import { sleep, useServer } from '@/tests/helpers';

/**
 * Keyspace notifications, as documented on redis.io ("Redis keyspace notifications"): channel names, event classes and
 * the "Events generated by different commands" list.
 */
const t = useServer();

type Msg = [channel: string, message: string];

/** Subscribes to every keyspace / keyevent channel and records what arrives, in order. */
async function listen(): Promise<{ sub: Redis; msgs: Msg[]; events: () => Promise<Msg[]> }> {
  const sub = t.client();
  const msgs: Msg[] = [];
  sub.on('pmessage', (_pattern: string, channel: string, message: string) => msgs.push([channel, message]));
  await sub.psubscribe('__key*__:*');
  return {
    sub,
    msgs,
    events: async () => {
      await sleep(40);
      return msgs.splice(0);
    },
  };
}

/** Only the keyevent messages (`event`, `key`), which keep the examples short. */
const keyevents = (msgs: Msg[]): Array<[string, string]> =>
  msgs.filter(([ch]) => ch.startsWith('__keyevent@')).map(([ch, key]) => [ch.slice(ch.indexOf(':') + 1), key]);

let l: Awaited<ReturnType<typeof listen>>;

beforeEach(async () => {
  await t.call('FLUSHALL');
  await t.call('CONFIG', 'SET', 'notify-keyspace-events', 'KEA');
  l ??= await listen();
  await l.events();
});

describe('channels and classes', () => {
  it('publishes __keyspace@<db>__:<key> → event and __keyevent@<db>__:<event> → key', async () => {
    await t.call('SET', 'mykey', 'v');
    expect(await l.events()).toEqual([
      ['__keyspace@0__:mykey', 'set'],
      ['__keyevent@0__:set', 'mykey'],
    ]);
  });

  it('K only / E only / class filter', async () => {
    await t.call('CONFIG', 'SET', 'notify-keyspace-events', 'K$');
    await t.call('SET', 'a', '1');
    await t.call('SADD', 's', 'x');
    expect(await l.events()).toEqual([['__keyspace@0__:a', 'set']]);
    await t.call('CONFIG', 'SET', 'notify-keyspace-events', 'Es');
    await t.call('SET', 'a', '2');
    await t.call('SADD', 's', 'y');
    expect(await l.events()).toEqual([['__keyevent@0__:sadd', 's']]);
    await t.call('CONFIG', 'SET', 'notify-keyspace-events', '');
    await t.call('SET', 'a', '3');
    expect(await l.events()).toEqual([]);
  });

  it('uses the database of the command', async () => {
    const c = t.client();
    await c.select(3);
    await c.set('k', 'v');
    expect(keyevents(await l.events())).toEqual([['set', 'k']]);
    expect(l.msgs).toEqual([]);
    c.disconnect();
  });
});

describe('events generated by different commands', () => {
  it('DEL generates a del event for every deleted key', async () => {
    await t.call('MSET', 'a', '1', 'b', '2');
    await l.events();
    await t.call('DEL', 'a', 'b', 'missing');
    expect(keyevents(await l.events())).toEqual([
      ['del', 'a'],
      ['del', 'b'],
    ]);
  });

  it('RENAME: rename_from then rename_to', async () => {
    await t.call('SET', 'src', 'v');
    await l.events();
    await t.call('RENAME', 'src', 'dst');
    expect(keyevents(await l.events())).toEqual([
      ['rename_from', 'src'],
      ['rename_to', 'dst'],
    ]);
  });

  it('MOVE: move_from in the source db, move_to in the destination db', async () => {
    await t.call('SET', 'mv', 'v');
    await l.events();
    await t.call('MOVE', 'mv', '2');
    expect(await l.events()).toEqual([
      ['__keyspace@0__:mv', 'move_from'],
      ['__keyevent@0__:move_from', 'mv'],
      ['__keyspace@2__:mv', 'move_to'],
      ['__keyevent@2__:move_to', 'mv'],
    ]);
  });

  it('COPY generates copy_to', async () => {
    await t.call('SET', 'c1', 'v');
    await l.events();
    await t.call('COPY', 'c1', 'c2');
    expect(keyevents(await l.events())).toEqual([['copy_to', 'c2']]);
  });

  it('EXPIRE: expire for a future time, only del for a time in the past', async () => {
    await t.call('SET', 'e', 'v');
    await l.events();
    await t.call('EXPIRE', 'e', '100');
    expect(keyevents(await l.events())).toEqual([['expire', 'e']]);
    await t.call('PEXPIREAT', 'e', '1');
    expect(keyevents(await l.events())).toEqual([['del', 'e']]);
  });

  it('SET variants generate set; SETEX also expire; MSET one set per key', async () => {
    await t.call('SETEX', 'x', '100', 'v');
    expect(keyevents(await l.events())).toEqual([
      ['set', 'x'],
      ['expire', 'x'],
    ]);
    await t.call('SETNX', 'y', 'v');
    await t.call('GETSET', 'y', 'w');
    await t.call('MSET', 'm1', '1', 'm2', '2');
    expect(keyevents(await l.events())).toEqual([
      ['set', 'y'],
      ['set', 'y'],
      ['set', 'm1'],
      ['set', 'm2'],
    ]);
  });

  it('a SET that did not store anything is silent (NX / XX, with or without GET)', async () => {
    await t.call('SET', 'k', 'v');
    await l.events();
    expect(await t.call('SET', 'k', 'w', 'NX')).toBeNull();
    expect(await t.call('SET', 'k', 'w', 'NX', 'GET')).toBe('v');
    expect(await t.call('SET', 'nokey', 'w', 'XX', 'GET')).toBeNull();
    expect(keyevents(await l.events())).toEqual([]);
    // SET … GET on a missing key does store the value
    expect(await t.call('SET', 'fresh', 'w', 'GET')).toBeNull();
    expect(keyevents(await l.events())).toEqual([['set', 'fresh']]);
  });

  it('SETRANGE, APPEND; INCR, DECR, INCRBY, DECRBY all generate incrby; INCRBYFLOAT incrbyfloat', async () => {
    await t.call('SETRANGE', 's', '0', 'abc');
    await t.call('APPEND', 's', 'd');
    await t.call('INCR', 'n');
    await t.call('DECR', 'n');
    await t.call('INCRBY', 'n', '5');
    await t.call('DECRBY', 'n', '2');
    await t.call('INCRBYFLOAT', 'n', '1.5');
    expect(keyevents(await l.events())).toEqual([
      ['setrange', 's'],
      ['append', 's'],
      ['incrby', 'n'],
      ['incrby', 'n'],
      ['incrby', 'n'],
      ['incrby', 'n'],
      ['incrbyfloat', 'n'],
    ]);
  });

  it('lists: one lpush / rpush per call; pops and removals add del when the list is gone', async () => {
    await t.call('LPUSH', 'l', 'a', 'b', 'c');
    await t.call('RPUSH', 'l', 'd');
    await t.call('LINSERT', 'l', 'BEFORE', 'a', 'z');
    await t.call('LSET', 'l', '0', 'q');
    await t.call('LREM', 'l', '0', 'z');
    await t.call('LTRIM', 'l', '0', '0');
    await t.call('RPOP', 'l');
    expect(keyevents(await l.events())).toEqual([
      ['lpush', 'l'],
      ['rpush', 'l'],
      ['linsert', 'l'],
      ['lset', 'l'],
      ['lrem', 'l'],
      ['ltrim', 'l'],
      ['rpop', 'l'],
      ['del', 'l'],
    ]);
  });

  it('RPOPLPUSH / LMOVE: the pop event is always delivered before the push event', async () => {
    await t.call('RPUSH', 'src', 'a', 'b');
    await l.events();
    await t.call('RPOPLPUSH', 'src', 'dst');
    await t.call('LMOVE', 'src', 'dst', 'LEFT', 'RIGHT');
    const got = keyevents(await l.events()).filter(([e]) => e !== 'del');
    expect(got).toEqual([
      ['rpop', 'src'],
      ['lpush', 'dst'],
      ['lpop', 'src'],
      ['rpush', 'dst'],
    ]);
  });

  it('hashes: hset for HSET / HSETNX / HMSET, hincrby, hincrbyfloat, hdel (+ del)', async () => {
    await t.call('HSET', 'h', 'a', '1', 'b', '2');
    await t.call('HSETNX', 'h', 'c', '3');
    await t.call('HMSET', 'h', 'd', '4');
    await t.call('HINCRBY', 'h', 'a', '1');
    await t.call('HINCRBYFLOAT', 'h', 'a', '0.5');
    await t.call('HDEL', 'h', 'a', 'b', 'c', 'd');
    expect(keyevents(await l.events())).toEqual([
      ['hset', 'h'],
      ['hset', 'h'],
      ['hset', 'h'],
      ['hincrby', 'h'],
      ['hincrbyfloat', 'h'],
      ['hdel', 'h'],
      ['del', 'h'],
    ]);
  });

  it('sets: sadd, srem (+ del), smove, spop, *store and del for an empty result on an existing key', async () => {
    await t.call('SADD', 's1', 'a', 'b');
    await t.call('SMOVE', 's1', 's2', 'a');
    await t.call('SPOP', 's1');
    await t.call('SADD', 'dst', 'x');
    await t.call('SINTERSTORE', 'dst', 's1', 's2');
    await t.call('SUNIONSTORE', 'u', 's2');
    await t.call('SREM', 'u', 'a');
    expect(keyevents(await l.events())).toEqual([
      ['sadd', 's1'],
      ['srem', 's1'],
      ['sadd', 's2'],
      ['spop', 's1'],
      ['del', 's1'],
      ['sadd', 'dst'],
      ['del', 'dst'],
      ['sunionstore', 'u'],
      ['srem', 'u'],
      ['del', 'u'],
    ]);
  });

  it('sorted sets: zadd, zincr, zrem (+ del), zrembyscore, zrembyrank, *store', async () => {
    await t.call('ZADD', 'z', '1', 'a', '2', 'b', '3', 'c', '4', 'd');
    await t.call('ZINCRBY', 'z', '1', 'a');
    await t.call('ZREMRANGEBYSCORE', 'z', '4', '4');
    await t.call('ZREMRANGEBYRANK', 'z', '0', '0');
    await t.call('ZUNIONSTORE', 'zu', '1', 'z');
    await t.call('ZREM', 'z', 'a', 'b', 'c', 'd');
    expect(keyevents(await l.events())).toEqual([
      ['zadd', 'z'],
      ['zincr', 'z'],
      ['zrembyscore', 'z'],
      ['zrembyrank', 'z'],
      ['zunionstore', 'zu'],
      ['zrem', 'z'],
      ['del', 'z'],
    ]);
  });

  it('streams: xadd (+ xtrim only when entries were trimmed), xdel, xgroup-*, xsetid, xtrim', async () => {
    await t.call('XADD', 'st', '1-1', 'f', 'v');
    await t.call('XADD', 'st', 'MAXLEN', '5', '2-1', 'f', 'v');
    await t.call('XADD', 'st', 'MAXLEN', '1', '3-1', 'f', 'v');
    await t.call('XGROUP', 'CREATE', 'st', 'g', '0');
    await t.call('XGROUP', 'CREATECONSUMER', 'st', 'g', 'c');
    await t.call('XGROUP', 'DELCONSUMER', 'st', 'g', 'c');
    await t.call('XGROUP', 'SETID', 'st', 'g', '0');
    await t.call('XGROUP', 'DESTROY', 'st', 'g');
    await t.call('XSETID', 'st', '10-1');
    await t.call('XADD', 'st', '11-1', 'f', 'v');
    await t.call('XDEL', 'st', '11-1');
    await t.call('XTRIM', 'st', 'MAXLEN', '0');
    expect(keyevents(await l.events())).toEqual([
      ['xadd', 'st'],
      ['xadd', 'st'],
      ['xadd', 'st'],
      ['xtrim', 'st'],
      ['xgroup-create', 'st'],
      ['xgroup-createconsumer', 'st'],
      ['xgroup-delconsumer', 'st'],
      ['xgroup-setid', 'st'],
      ['xgroup-destroy', 'st'],
      ['xsetid', 'st'],
      ['xadd', 'st'],
      ['xdel', 'st'],
      ['xtrim', 'st'],
    ]);
  });

  it('PERSIST generates persist only when a TTL was removed', async () => {
    await t.call('SET', 'p', 'v', 'EX', '100');
    await l.events();
    await t.call('PERSIST', 'p');
    await t.call('PERSIST', 'p');
    expect(keyevents(await l.events())).toEqual([['persist', 'p']]);
  });

  it('SORT … STORE generates sortstore', async () => {
    await t.call('RPUSH', 'nums', '3', '1', '2');
    await l.events();
    await t.call('SORT', 'nums', 'STORE', 'sorted');
    expect(keyevents(await l.events())).toEqual([['sortstore', 'sorted']]);
  });

  it('commands inside MULTI/EXEC and scripts notify like top-level ones', async () => {
    const c = t.client();
    await c.multi().set('tx', '1').incr('tx').exec();
    await c.eval("redis.call('SET', KEYS[1], 'v'); redis.call('DEL', KEYS[1])", 1, 'lua');
    expect(keyevents(await l.events())).toEqual([
      ['set', 'tx'],
      ['incrby', 'tx'],
      ['set', 'lua'],
      ['del', 'lua'],
    ]);
    c.disconnect();
  });

  it('a blocked client that gets served notifies its pop', async () => {
    const blocker = t.client();
    const pending = blocker.blpop('bl', 0);
    await sleep(30);
    await t.call('RPUSH', 'bl', 'x');
    expect(await pending).toEqual(['bl', 'x']);
    expect(keyevents(await l.events())).toEqual([
      ['rpush', 'bl'],
      ['lpop', 'bl'],
      ['del', 'bl'],
    ]);
    blocker.disconnect();
  });
});

describe('expired, new and keymiss', () => {
  it('expired (x): when a key with a TTL is removed because it expired', async () => {
    await t.call('CONFIG', 'SET', 'notify-keyspace-events', 'Ex');
    await t.call('SET', 'ttl', 'v', 'PX', '20');
    await sleep(60);
    await t.call('GET', 'ttl');
    expect(await l.events()).toEqual([['__keyevent@0__:expired', 'ttl']]);
  });

  it('new (n): only when a key is added; not part of A', async () => {
    await t.call('CONFIG', 'SET', 'notify-keyspace-events', 'En');
    await t.call('SET', 'k', '1');
    await t.call('SET', 'k', '2');
    await t.call('RPUSH', 'list', 'a');
    await t.call('RPUSH', 'list', 'b');
    expect(await l.events()).toEqual([
      ['__keyevent@0__:new', 'k'],
      ['__keyevent@0__:new', 'list'],
    ]);
    await t.call('CONFIG', 'SET', 'notify-keyspace-events', 'KEA');
    await t.call('SET', 'k2', '1');
    expect(keyevents(await l.events())).toEqual([['set', 'k2']]);
  });

  it('new is delivered before the command event', async () => {
    await t.call('CONFIG', 'SET', 'notify-keyspace-events', 'EAn');
    await t.call('HSET', 'nh', 'f', 'v');
    expect(keyevents(await l.events())).toEqual([
      ['new', 'nh'],
      ['hset', 'nh'],
    ]);
  });

  it('keymiss (m): reading a missing key; not part of A', async () => {
    await t.call('CONFIG', 'SET', 'notify-keyspace-events', 'KEm');
    await t.call('SET', 'here', 'v');
    await t.call('GET', 'here');
    await t.call('GET', 'missing');
    await t.call('MGET', 'here', 'gone');
    expect(await l.events()).toEqual([
      ['__keyspace@0__:missing', 'keymiss'],
      ['__keyevent@0__:keymiss', 'missing'],
      ['__keyspace@0__:gone', 'keymiss'],
      ['__keyevent@0__:keymiss', 'gone'],
    ]);
    await t.call('CONFIG', 'SET', 'notify-keyspace-events', 'KEA');
    await t.call('GET', 'missing');
    expect(await l.events()).toEqual([]);
  });
});
